const pain = String($json.pain || '').toLowerCase();
let score = 0;
if (pain.includes('0') || pain.includes('no sales') || pain.includes('zero revenue')) score += 35;
if (pain.includes('tool') || pain.includes('subscription') || pain.includes('limit')) score += 20;
if (Number($json.budget || 0) >= 9) score += 25;
if (['today','now','48h','urgent'].includes(String($json.urgency || '').toLowerCase())) score += 20;
return [{ json: { ...$json, score, segment: score >= 60 ? 'hot' : score >= 35 ? 'warm' : 'cold' } }];
